#!/bin/sh
# kernel_report_check.sh -- the checked-in kernel report is internally consistent.
#
# docs/KERNELS.md is generated by `rad-kbench --report` and reviewed by hand. A hand-merged
# regeneration can carry a per-library "N row(s) not reached" header from one run and the table
# below it from another: at v1.13.0 the libr4d header says 239 while its table lists 243 rows
# (the four kv_store_streamed rows landed in 486c9331 without the count moving), so the section
# total (378) and the headline "132 of 510 declared row(s) were reached" both read four rows
# short of the tables. The generator cannot produce this from one run -- header and table come
# from one vector -- so the report is checked here, and a partially regenerated file fails.
#
# A check that cannot fail is not a check (docs/DEVLOG-decode-floor.md).
set -u
REPORT=$1
test -f "$REPORT" || { echo "kernel_report_check: no report at $REPORT"; exit 1; }
# The counting is one python3 pass; a host without it skips, like ops_doc's skip codes.
command -v python3 >/dev/null 2>&1 || { echo "  SKIP python3 not present"; exit 77; }

python3 - "$REPORT" <<'PY'
import re, sys
lines = open(sys.argv[1]).read().split("\n")
pat = re.compile(r"`lib\w+`: (\d+) row\(s\) not reached:")
heads = [(i, m.group(1)) for i, l in enumerate(lines) if (m := pat.match(l))]
bad = 0
for j, (a, claimed) in enumerate(heads):
    # The library's table ends at the next library header or the next section header.
    b = len(lines)
    for i in range(a + 1, len(lines)):
        if pat.match(lines[i]) or lines[i].startswith("## "):
            b = i
            break
    rows = sum(1 for l in lines[a:b] if l.startswith("| `"))
    name = re.match(r"`(\w+)`", lines[a]).group(1)
    print(f"  {name}: header {claimed}, table {rows}")
    if int(claimed) != rows:
        bad += 1
text = "\n".join(lines)
m = re.search(r"(\d+) of (\d+) declared row\(s\) were reached", text)
if m:
    ran, declared = int(m.group(1)), int(m.group(2))
    missed = sum(int(x) for x in pat.findall(text))
    if ran + missed != declared:
        print(f"  headline: {ran} reached + {missed} not reached != {declared} declared")
        bad += 1
if bad:
    print(f"kernel_report_check: {bad} inconsistent count(s); regenerate the report from one run.")
    sys.exit(1)
print("kernel_report_check: the report's counts agree.")
PY
